export function deprecationMiddleware(req: Request, res: Response, next: NextFunction) {
  // Signal API deprecation using standard IETF RFC headers
  res.setHeader("Deprecation", "@1727913600"); // Unix timestamp
  res.setHeader("Sunset", "Wed, 31 Dec 2026 23:59:59 GMT");
  res.setHeader(
    "Link",
    '<https://api.example.com/docs/v1-migration>; rel="sunset"; type="text/html"'
  );
  next();
}

// Base64-encoded opaque cursor: { created_at: "2026-10-03T12:00:00Z", id: 98124 }
export async function fetchCursorPage(cursorToken?: string, limit = 20) {
  let query = `
    SELECT id, title, created_at
    FROM posts
  `;
  const params: any[] = [];

  if (cursorToken) {
    const { createdAt, id } = decodeCursor(cursorToken);
    // Composite comparison seeks directly via (created_at, id) composite index
    query += ` WHERE (created_at, id) < ($1, $2)`;
    params.push(createdAt, id);
  }

  query += ` ORDER BY created_at DESC, id DESC LIMIT $${params.length + 1}`;
  params.push(limit + 1); // Fetch 1 extra to determine if next page exists

  const rows = await db.query(query, params);
  const hasMore = rows.length > limit;
  const items = hasMore ? rows.slice(0, limit) : rows;
  const nextCursor = hasMore ? encodeCursor(items[items.length - 1]) : null;

  return { items, nextCursor };
}

export async function handleIdempotentRequest(
  key: string,
  reqHandler: () => Promise<{ status: number; body: any }>
) {
  const redisKey = `idempotency:${key}`;

  // 1. Attempt atomic lock acquisition (NX = only set if not exists)
  const acquired = await redis.set(redisKey, JSON.stringify({ state: 'PROCESSING' }), 'NX', 'EX', 120);

  if (!acquired) {
    const existing = JSON.parse((await redis.get(redisKey))!);
    if (existing.state === 'PROCESSING') {
      // Concurrent request in-flight; reject duplicate execution
      return { status: 409, body: { error: 'Request currently processing' } };
    }
    // Previously completed; return identical cached response directly
    return { status: existing.status, body: existing.body };
  }

  try {
    // 2. Execute business logic
    const response = await reqHandler();
    // 3. Cache completed outcome for 24 hours
    await redis.set(redisKey, JSON.stringify({ state: 'COMPLETED', ...response }), 'EX', 86400);
    return response;
  } catch (err) {
    // Remove lock on unexpected failure so client can retry
    await redis.del(redisKey);
    throw err;
  }
}

import jwt from 'jsonwebtoken';

interface TokenPayload {
  sub: string;       // User ID
  roles: string[];   // Assigned roles for RBAC
  iss: string;       // Issuer authority
}

export function verifyAccessToken(token: string, publicKeyPem: string): TokenPayload {
  // Verify signature locally using asymmetric public key (RS256 / EdDSA)
  return jwt.verify(token, publicKeyPem, {
    algorithms: ['RS256'],
    issuer: 'https://auth.example.com/',
  }) as TokenPayload;
}
